create extension if not exists "pgcrypto"; create extension if not exists "uuid-ossp";
drop table if exists public.api_keys cascade; drop table if exists public.profiles cascade;
drop function if exists public.handle_new_user() cascade; drop function if exists public.generate_api_key(uuid,text) cascade; drop function if exists public.verify_api_key(text) cascade;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, email text, full_name text, poi_points int default 100, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.api_keys (id uuid primary key default uuid_generate_v4(), user_id uuid not null references auth.users(id) on delete cascade, name text not null default 'SEARCH-POI ENGINE v1', key_prefix text not null, key_hash text not null, key_preview text not null, full_key text not null, is_active boolean default true, usage_count int default 0, last_used_at timestamptz, created_at timestamptz default now(), requests_per_minute int default 60, daily_quota int default 1000);
create or replace function public.handle_new_user() returns trigger as $$ begin insert into public.profiles (id, email, full_name) values (new.id, new.email, new.raw_user_meta_data->>'full_name') on conflict (id) do update set email=excluded.email, updated_at=now(); return new; end; $$ language plpgsql security definer set search_path=public;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
insert into public.profiles (id, email) select id, email from auth.users on conflict (id) do nothing;
create or replace function public.generate_api_key(p_user_id uuid, p_name text default 'SEARCH-POI ENGINE v1') returns table (id uuid, full_key text, key_preview text, name text, key_prefix text) as $$ declare v_full_key text; v_prefix text; v_hash text; v_preview text; v_id uuid; begin v_full_key:='sk-poi-'||encode(gen_random_bytes(24),'hex'); v_prefix:=substring(v_full_key,1,12); v_hash:=crypt(v_full_key, gen_salt('bf',8)); v_preview:=substring(v_full_key,1,12)||'...'||substring(v_full_key,length(v_full_key)-3,4); insert into public.api_keys (user_id, name, key_prefix, key_hash, key_preview, full_key) values (p_user_id, p_name, v_prefix, v_hash, v_preview, v_full_key) returning api_keys.id into v_id; return query select v_id, v_full_key, v_preview, p_name, v_prefix; end; $$ language plpgsql security definer set search_path=public;
create or replace function public.verify_api_key(p_raw_key text) returns table (user_id uuid, key_id uuid, is_valid boolean, name text, requests_per_minute int) as $$ begin return query select ak.user_id, ak.id, true, ak.name, ak.requests_per_minute from public.api_keys ak where ak.full_key=p_raw_key and ak.is_active=true limit 1; if not found then return query select ak.user_id, ak.id, true, ak.name, ak.requests_per_minute from public.api_keys ak where crypt(p_raw_key, ak.key_hash)=ak.key_hash and ak.is_active=true limit 1; end if; update public.api_keys set usage_count=usage_count+1, last_used_at=now() where full_key=p_raw_key or crypt(p_raw_key, key_hash)=key_hash; end; $$ language plpgsql security definer set search_path=public;
alter table public.profiles enable row level security; alter table public.api_keys enable row level security;
drop policy if exists "Users can view own profile" on public.profiles; create policy "Users can view own profile" on public.profiles for select using (auth.uid()=id);
drop policy if exists "Users can update own profile" on public.profiles; create policy "Users can update own profile" on public.profiles for update using (auth.uid()=id);
drop policy if exists "Users can insert own profile" on public.profiles; create policy "Users can insert own profile" on public.profiles for insert with check (auth.uid()=id);
drop policy if exists "Users can view own keys" on public.api_keys; create policy "Users can view own keys" on public.api_keys for select using (auth.uid()=user_id);
drop policy if exists "Users can create own keys" on public.api_keys; create policy "Users can create own keys" on public.api_keys for insert with check (auth.uid()=user_id);
drop policy if exists "Users can delete own keys" on public.api_keys; create policy "Users can delete own keys" on public.api_keys for delete using (auth.uid()=user_id);
drop policy if exists "Users can update own keys" on public.api_keys; create policy "Users can update own keys" on public.api_keys for update using (auth.uid()=user_id);
